select 'missing_or_mismatched_issue98_slice2_identities' check_name, count(*) affected_rows
from expected e left join public.exercise_identities i on i.id = e.id
where i.id is null or i.owner_scope <> 'system' or not i.active or i.superseded_by is not null
   or (i.display_name, i.normalized_lookup_key, i.equipment_tags, i.movement_pattern, i.qualifier_text, i.metadata)
      is distinct from (e.display_name, e.normalized_lookup_key, e.equipment_tags, e.movement_pattern, e.qualifier_text, e.metadata)
union all
select 'canonical_name_collisions', count(*) from expected e join public.exercise_identities i on i.normalized_lookup_key=e.normalized_lookup_key where i.active and i.id<>e.id
union all
select 'reviewed_alias_collisions', count(*) from expected e join public.exercise_aliases a on a.normalized_lookup_key=e.normalized_lookup_key where a.reviewed
union all
select 'unexpected_user_ownership', count(*) from expected e join public.exercise_identities i on i.id=e.id where i.owner_scope<>'system';
